declare namespace SigApi {
    interface Checkbit {
        /**
         * Returns the id of the checkbit
         * 
         * @returns {string} The id of the checkbit
         */
        getId(): string
        /**
         * Returns the current value of the checkbit
         * 
         * @returns {boolean} The current value of the checkbit
         */
        getValue(): boolean
        /**
         * Awaits all async operations and returns the value of the checkbit
         * 
         * @returns {Promise<boolean>} Returns a Promise which returns the value of the checkbit when the Promise has been resolved.
         */
        getValueForced(): Promise<boolean>
    }
}
